parameters.jsCode:
const items = $input.all();
const content = items[0].json.message.content;

let themes;
try {
  const jsonMatch = content.match(/\[.*\]/s);
  themes = jsonMatch ? JSON.parse(jsonMatch[0]) : [];
} catch (e) {
  themes = [{ theme: 'Parse Error', summary: content }];
}

const totalResponses = themes.reduce((sum, t) => sum + (t.frequency || 0), 0);

const quantified = themes.map(t => ({
  ...t,
  percentage: totalResponses > 0 ? ((t.frequency || 0) / totalResponses * 100).toFixed(1) + '%' : '0%'
}));

const sentimentBreakdown = {
  positive: themes.filter(t => t.sentiment === 'positive').length,
  negative: themes.filter(t => t.sentiment === 'negative').length,
  neutral: themes.filter(t => t.sentiment === 'neutral').length,
  mixed: themes.filter(t => t.sentiment === 'mixed').length
};

return [{
  json: {
    themeCount: themes.length,
    totalResponses,
    sentimentBreakdown,
    themes: quantified,
    reportDate: new Date().toISOString()
  }
}];

